Notation amem := (word -> option byte).

Definition w4s_B2_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x16 x17 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word)
         (P SS n SBL SBH S2 l : Z) (w0 w96 w104 w200 w208 : word),
    w4s_src_ctx RNG mm SS n SBL SBH ->
    ztab_fact asegs mm (S2 + l - 1) 1 1 [(0, 1, 255)] ->
    SS + 6 <= S2 -> 8 <= l < 65536 -> S2 + l <= SS + n ->
    rw_cells asegs mm P [C8 w0] -> rw_cells asegs mm (P + 96) [C8 w96] -> rw_cells asegs mm (P + 104) [C8 w104] ->
    rw_cells asegs mm (P + 200) [C8 w200] -> rw_cells asegs mm (P + 208) [C8 w208] ->
    rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    rng RNG P 496 -> 0x10007fff8000 <= P -> P + 496 <= 2^47 -> SS + n <= P ->
    (forall (r : Z) (a5 a6 a7 : word) (mm' : amem), 1 <= r <= 255 ->
       munch [(P, P + 8); (P + 96, P + 112); (P + 200, P + 216)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
       rw_cells asegs mm' P [C8 x14] -> rw_cells asegs mm' (P + 96) [C8 x19] -> rw_cells asegs mm' (P + 104) [C8 x28] ->
       rw_cells asegs mm' (P + 200) [C8 x29] -> rw_cells asegs mm' (P + 208) [C8 x21] ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 (Z_to_bv 64 (S2 + l)) x9 x10 (Z_to_bv 64 r)
                                 (Z_to_bv 64 (S2 + l + -1)) x13 x14 a5 a6 a7 (Z_to_bv 64 S2) x19 x20 x21 x22 x23 x24
                                 (Z_to_bv 64 (S2 + l + -8)) x26 x27 x28 x29 x30 x31)
                            F (Z_to_bv 64 0x905f0) fc None mm' (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 (Z_to_bv 64 l) x16 x17
                             (Z_to_bv 64 S2) x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                        F (Z_to_bv 64 0x90584) fc None mm (seg_rom asegs)).

