(* [comment removed for export] *)
Definition w4s_S2_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x16 x17 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word)
         (P SS n SBL SBH S2 l lo hi : Z) (w0 : word),
    w4s_src_ctx RNG mm SS n SBL SBH ->
    ztab_fact asegs mm (S2 + l - 1) 1 1 [(0, lo, hi)] -> (lo = 1 /\ hi = 255 \/ lo = 0 /\ hi = 0) ->
    SS + 6 <= S2 -> 1 <= l <= 7 -> S2 + l <= SS + n ->
    rw_cells asegs mm P [C8 w0] -> rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    rng RNG P 496 -> 0x10007fff8000 <= P -> P + 496 <= 2^47 -> SS + n <= P ->
    (forall (r : Z) (a2 c a6 : word) (mm' : amem), 1 <= r <= 255 -> lo = 1 ->
       munch [(P, P + 8)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' -> rw_cells asegs mm' P [C8 x14] ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 (Z_to_bv 64 (S2 + l)) x9 x10 (Z_to_bv 64 r) a2 x13 c
                                 (Z_to_bv 64 l) a6 x17 (Z_to_bv 64 S2) x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                            F (Z_to_bv 64 0x90824) fc None mm' (seg_rom asegs))) ->
    (forall (a1 a2 c a6 : word) (mm' : amem), lo = 0 ->
       munch [(P, P + 8)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' -> rw_cells asegs mm' P [C8 x14] ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 (Z_to_bv 64 (S2 + l)) x9 x10 a1 a2 x13 c
                                 (Z_to_bv 64 l) a6 x17 (Z_to_bv 64 S2) x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                            F (Z_to_bv 64 0x91bc0) fc None mm' (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 (Z_to_bv 64 l) x16 x17
                             (Z_to_bv 64 S2) x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                        F (Z_to_bv 64 0x90584) fc None mm (seg_rom asegs)).

Ltac w4s_small2_post K K0 C0 P S2 l :=
  kx_post_regs_keep;
  lazymatch goal with H : log_flat ?E' ?log |- _ => rename H into HLF end;
  let MU := fresh "MU" in let WM := fresh "WM" in
  lazymatch goal with |- context [MS _ _ _ _ _ (mem_denot _ ?m _) _] =>
    pose proof (munch_refl [(P, P + 8)] m) as MU; pose proof (wmono_refl asegs m) as WM end;
  kx_munch_wins MU [(P, 8)];
  kx_post_mem_free;
  kx_cell C0;
  replace (l + S2) with (S2 + l) by apply Z.add_comm;
  lazymatch goal with
  | |- evtF _ _ _ (MS _ _ (Z_to_bv 64 0x91bf0) _ _ _ _) => eapply K0; [ reflexivity | exact MU | exact WM | eassumption | exact C0 ]
  | |- evtF _ _ _ (MS (mkR _ _ _ _ _ _ _ _ _ _ (ev ?E' ?j) _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _) _ _ _ _ _ _) =>
      let H := fresh "H" in kx_range (EVar j) H;
      replace (ev E' j) with (Z_to_bv 64 (bv_unsigned (ev E' j))) by (apply Z_to_bv_bv_unsigned);
      eapply (K (bv_unsigned (ev E' j))); [ exact H | reflexivity | exact MU | exact WM | eassumption | exact C0 ]
  end.

